SELECT o.${kind.idCol} AS id, o.${kind.nameCol} AS name, (SELECT COUNT(*) FROM employee e JOIN user_account a ON a.employee_id = e.employee_id AND a.company_id = e.company_id WHERE e.company_id = o.company_id AND e.${kind.idCol} = o.${kind.idCol} AND a.status_code = 'ACTIVE') AS in_use, (SELECT COUNT(*) FROM employee e JOIN user_account a ON a.employee_id = e.employee_id AND a.company_id = e.company_id WHERE e.company_id = o.company_id AND e.${kind.idCol} = o.${kind.idCol} AND a.status_code != 'ACTIVE') AS retired, (SELECT COUNT(*) FROM account_request r WHERE r.company_id = o.company_id AND r.${kind.idCol} = o.${kind.idCol} AND r.status_code = 'REQUESTED') AS requests
, o.department_type AS type , (SELECT h.employee_name FROM employee h WHERE h.company_id = o.company_id AND h.employee_id = o.head_employee_id) AS head_name
FROM ${kind.table} o WHERE o.company_id = #{companyId} AND o.use_yn = 'Y' ORDER BY o.sort_order, o.${kind.nameCol}

SELECT ${kind.idCol} AS id, ${kind.nameCol} AS name
FROM ${kind.table}
WHERE company_id = #{companyId}
  AND use_yn = 'Y'
ORDER BY sort_order, ${kind.nameCol}
FOR UPDATE

